      "protectionUnit": "福州海峡茶业交流协会",
      "descriptionZh": "福州茉莉花茶把茶坯与鲜花拼和窨制，让茶吸收花香，再将茶与花分开。",
      "descriptionEn": "Fuzhou jasmine tea is scented by combining tea with fresh jasmine flowers, then separating the tea from the flowers.",
      "imageUrl": "",
      "videoUrl": "",
