      "detailSections": [
        {
          "key": "overview",
          "titleZh": "项目简介",
          "contentZh": "福州茉莉花茶把茶坯与鲜花拼和窨制，让茶吸收花香，再将茶与花分开。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Fuzhou jasmine tea is scented by combining tea with fresh jasmine flowers, then separating the tea from the flowers.",
          "titleEn": "Introduction"
        },
        {
          "key": "practice",
          "titleZh": "核心工艺",
          "contentZh": "窨花时，茶坯与茉莉鲜花接触，使茶香与花香相融。通花要根据茶花堆的温度、水分和鲜花状态掌握，随后收堆复窨。起花将茶与花分开；烘焙则排除多余水分，同时减少香气散失。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "During scenting, the tea base is mixed with fresh jasmine flowers so that it absorbs their fragrance. Makers aerate the mixture according to its temperature, moisture and the condition of the flowers, then gather it again for further scenting. The flowers are separated from the tea; baking removes excess moisture while limiting the loss of aroma.",
          "titleEn": "Tea-making craft"
        },
        {
          "key": "history",
          "titleZh": "历史脉络",
          "contentZh": "福州茉莉花茶在北宋已有相关记述，窨制工艺在明代逐渐定型。宋代词作与明代茶书中，也留下了茉莉与茶相结合的记录。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Accounts of Fuzhou jasmine tea date to the Northern Song dynasty. Its scenting techniques gradually took shape in the Ming dynasty. Song poetry and Ming tea books also record the pairing of jasmine and tea.",
          "titleEn": "History"
        },
        {
          "key": "inheritance",
          "titleZh": "传承保护",
          "contentZh": "这项技艺依靠口传心授延续，制茶人需要结合鲜花品质与茶坯情况把握窨制。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "The craft is passed on through oral instruction and hands-on teaching. Makers adjust scenting to the quality of the flowers and the condition of the tea base.",
          "titleEn": "Passing on the tradition"
        }
      ],
