      "descriptionZh": "安溪铁观音属于乌龙茶，摇青以及反复包揉、烘焙，是传统制作中的重要环节。",
      "descriptionEn": "Anxi Tieguanyin is an oolong tea. Shaking the leaves, repeated wrapped rolling and roasting are important parts of its craft.",
      "imageUrl": "",
      "videoUrl": "",
      "sourceUrl": "https://www.ihchina.cn/project_details/14620.html",
      "sourceStatus": "official-partial",
