      "detailSections": [
        {
          "key": "overview",
          "titleZh": "项目简介",
          "contentZh": "安溪铁观音属于乌龙茶，摇青以及反复包揉、烘焙，是传统制作中的重要环节。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Anxi Tieguanyin is an oolong tea. Shaking the leaves, repeated wrapped rolling and roasting are important parts of its craft.",
          "titleEn": "Introduction"
        },
        {
          "key": "practice",
          "titleZh": "核心工艺",
          "contentZh": "传统制作分采摘、初制、精制三部分。初制依次包含晒青、凉青、摇青、炒青、揉捻、初烘、包揉、复烘、复包揉和烘干；精制还有筛分、拣剔、拼堆、烘焙、摊凉与包装。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "The traditional craft has three parts: picking, primary processing and refining. Primary processing includes sun-withering, cooling, shaking, pan-heating, rolling, initial drying, cloth-wrapped rolling, further drying, another wrapped rolling and final drying. Refining involves screening, sorting, blending, roasting, cooling and packing.",
          "titleEn": "Tea-making craft"
        },
        {
          "key": "cultural_value",
          "titleZh": "文化与地域",
          "contentZh": "制茶人结合季节、气候与鲜叶嫩度处理茶青。晒青、凉青、摇青使茶青发生变化，随后炒青、揉捻与反复包揉烘焙形成成茶风味。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Makers respond to the season, weather and tenderness of the fresh leaves. Sun-withering, cooling and shaking change the leaves; pan-heating, rolling and repeated wrapped rolling and roasting then help develop the finished tea.",
          "titleEn": "Culture and place"
        }
      ],
