      "id": "tea-item-06",
      "name": "乌龙茶制作技艺（漳平水仙茶制作技艺）",
      "nameEn": "Oolong Tea Processing Technique (Zhangping Shuixian)",
      "province": "福建省",
      "city": "龙岩市漳平市",
      "declaredRegion": "福建省龙岩市",
      "code": "Ⅷ-150",
      "category": "传统技艺",
      "yearBatch": "2021 第五批",
      "protectionUnit": "漳平市文化馆",
      "descriptionZh": "漳平水仙将乌龙茶制作与紧压包装结合，手艺通过师徒传授在闽西延续。",
      "descriptionEn": "Zhangping Shuixian combines oolong processing with compressed packaging. The craft is transmitted thunfinished teacher-apprentice relationships in western Fujian.",
      "imageUrl": "",
      "videoUrl": "",
      "sourceUrl": "https://www.ihchina.cn/project_details/23784.html",
      "sourceStatus": "official-partial",
      "dataQuality": "complete",
      "lastVerified": "2026-10-08",
      "detailSections": [
        {
          "key": "overview",
          "titleZh": "项目简介",
          "contentZh": "漳平水仙将乌龙茶制作与紧压包装结合，手艺通过师徒传授在闽西延续。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Zhangping Shuixian combines oolong processing with compressed packaging. The craft is transmitted thunfinished teacher-apprentice relationships in western Fujian.",
          "titleEn": "Introduction"
        },
        {
          "key": "history",
          "titleZh": "历史脉络",
          "contentZh": "清末，漳平双洋大会村茶农刘永发从建瓯水吉引进水仙茶苗，将闽北乌龙茶技艺与本地制作经验融合。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "In the late Qing dynasty, Liu Yongfa, a tea farmer from Dahui village in Shuangyang, Zhangping, introduced Shuixian tea plants from Shuiji in Jian'ou. He combined northern Fujian oolong techniques with local tea-making experience.",
          "titleEn": "History"
        },
        {
          "key": "practice",
          "titleZh": "核心工艺",
          "contentZh": "采茶时机与晒青处理随天气变化而调整。制茶人观察茶青颜色与香气，掌握摇青、炒青等工序，并采用紧压包装。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Picking times and sun-withering are adjusted to the weather. Makers observe leaf colour and aroma to guide shaking and pan-heating, and use compressed packaging.",
          "titleEn": "Tea-making craft"
        },
        {
          "key": "inheritance",
          "titleZh": "传承保护",
          "contentZh": "刘永发将手艺传给子孙，也传给客家人邓观金；邓观金又传给闽南人张旗生。这条师承联系体现了技艺在不同群体间的交流。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Liu Yongfa taught his descendants as well as Deng Guanjin, a Hakka practitioner. Deng later taught Zhang Qisheng, a southern Fujian practitioner. This teaching connection reflects the exchange of skills between communities.",
          "titleEn": "Passing on the tradition"
        }
      ],
      "representativeInheritors": [
        {
          "name": "张兴裕",
          "level": "",
          "note": "ihchina 项目页相关传承人"
        }
      ],
