      "keyFeatures": [
        {
          "textZh": "滇红茶以云南大叶种鲜叶为原料，经过萎凋、揉捻、发酵、干燥，成为红茶。",
          "sourceIds": [
            "ihchina-project"
          ],
          "textEn": "Dianhong black tea uses fresh leaves from Yunnan large-leaf tea plants and passes through withering, rolling, oxidation and drying."
        }
      ],
      "practiceExperience": {
        "titleZh": "一片鲜叶的四次变化",
        "titleEn": "Four changes of a tea leaf",
        "kind": "process",
        "noteZh": "沿着四道工序，看看一片鲜叶的变化。",
        "steps": [
          {
            "id": "dh-01",
            "titleZh": "萎凋",
            "titleEn": "Withering",
            "contentZh": "鲜叶自然失水，梗叶逐渐变软，为后续加工创造条件。",
            "sourceIds": [
              "ihchina-project"
            ],
            "assetId": "A02",
            "contentEn": "Fresh leaves naturally lose moisture. Their stems and blades gradually soften, preparing them for further processing."
          },
          {
            "id": "dh-02",
            "titleZh": "揉捻",
            "titleEn": "Rolling",
            "contentZh": "将软叶揉成条形；叶细胞受到破坏，为下一步发酵作准备。",
            "sourceIds": [
              "ihchina-project"
            ],
            "assetId": "A03",
            "contentEn": "The softened leaves are rolled into strips. Some leaf cells are broken, preparing the leaves for oxidation."
          },
          {
            "id": "dh-03",
            "titleZh": "发酵",
            "titleEn": "Oxidation",
            "contentZh": "在酶的作用下发生氧化反应，叶色由绿色逐渐出现微红或偏黄色变化。",
            "sourceIds": [
              "ihchina-project"
            ],
            "assetId": "A04",
            "contentEn": "Enzymes drive oxidation. The green leaves gradually develop reddish or yellowish tones."
          },
          {
            "id": "dh-04",
            "titleZh": "干燥",
            "titleEn": "Drying",
            "contentZh": "烘焙使茶坯水分蒸发，达到成茶所需的干度，并形成滇红茶的甜香。",
            "sourceIds": [
              "ihchina-project"
            ],
            "assetId": "A05",
            "contentEn": "Firing evaporates moisture to dry the tea and develop the sweet aroma of Dianhong."
          }
        ],
        "noteEn": "Follow four stages to see how a fresh tea leaf changes."
      },
