      "descriptionEn": "Pu'er tribute tea from Ning'er is made by processing fresh leaves into sun-dried tea, followed by steaming, rolling and pressing.",
      "imageUrl": "",
      "videoUrl": "",
      "sourceUrl": "https://www.ihchina.cn/project_details/14621.html",
