      "id": "tea-item-11",
      "name": "茶俗（白族三道茶）",
      "nameEn": "Tea Custom (Bai Three-Course Tea)",
      "province": "云南省",
      "city": "大理州大理市",
      "declaredRegion": "云南省大理市",
      "code": "Ⅹ-107",
      "category": "民俗",
      "yearBatch": "2014 第四批",
      "protectionUnit": "大理市非遗保护所",
      "descriptionZh": "白族三道茶以苦茶、甜茶、回味茶依次待客，把人生滋味融入茶礼。",
      "descriptionEn": "The Bai three-course tea ceremony welcomes guests with bitter, sweet and lingering tea, connecting their flavours with stages of life.",
      "imageUrl": "",
      "videoUrl": "",
      "sourceUrl": "https://www.ihchina.cn/project_details/15248.html",
      "sourceStatus": "needs-review",
      "dataQuality": "basic",
      "lastVerified": "2026-10-08",
      "detailSections": [
        {
          "key": "overview",
          "titleZh": "项目简介",
          "contentZh": "白族三道茶以苦茶、甜茶、回味茶依次待客，把人生滋味融入茶礼。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "The Bai three-course tea ceremony welcomes guests with bitter, sweet and lingering tea, connecting their flavours with stages of life.",
          "titleEn": "Introduction"
        },
        {
          "key": "history",
          "titleZh": "历史脉络",
          "contentZh": "明代徐霞客在大理旅行时曾受到三道茶款待，并在游记中记录了清茶、盐茶与蜜茶。茶礼随世代传承逐渐形成今天的表达。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "The Ming-dynasty traveller Xu Xiake was served three courses of tea in Dali. His travel journal records plain tea, salted tea and honey tea. The ceremony has developed its present expression through transmission across generations.",
          "titleEn": "History"
        },
        {
          "key": "practice",
          "titleZh": "礼俗与茶事",
          "contentZh": "第一道苦茶先烘茶再冲水，敬给客人；第二道甜茶加入核桃仁、红糖等，表达苦尽甘来；第三道回味茶将甜、微麻和苦等滋味相融，让人在品饮间回味人生。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "The first course is bitter tea: the leaves are roasted before water is added and the tea is offered to guests. The second, sweet tea, includes walnuts and brown sugar and expresses sweetness after hardship. The third combines sweet, gently tingling and bitter flavours, inviting reflection on life.",
          "titleEn": "Tea rituals"
        },
        {
          "key": "cultural_value",
          "titleZh": "文化与地域",
          "contentZh": "三道茶主要流布于云南大理，是节庆喜事和迎接宾客时的礼仪。依次敬茶，让主客交谈与人生感悟融入相聚。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Practised mainly in Dali, Yunnan, the ceremony welcomes guests and marks festivals and celebrations. Serving the courses in turn brings conversation and reflection into the gathering.",
          "titleEn": "Culture and place"
        }
      ],
