      "descriptionZh": "西湖龙井产于杭州西湖茶区，精细采摘与手工炒制相结合，形成了独特的制茶传统。",
      "descriptionEn": "West Lake Longjing comes from the West Lake tea-growing area in Hangzhou. Careful picking and skilled hand-processing define its craft.",
      "imageUrl": "",
      "videoUrl": "",
      "sourceUrl": "https://www.ihchina.cn/project_details/14605.html",
      "sourceStatus": "official-partial",
      "dataQuality": "basic",
      "lastVerified": "2026-10-08",
      "detailSections": [
        {
          "key": "overview",
          "titleZh": "项目简介",
          "contentZh": "西湖龙井产于杭州西湖茶区，精细采摘与手工炒制相结合，形成了独特的制茶传统。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "West Lake Longjing comes from the West Lake tea-growing area in Hangzhou. Careful picking and skilled hand-processing define its craft.",
          "titleEn": "Introduction"
        },
        {
          "key": "practice",
          "titleZh": "核心工艺",
          "contentZh": "西湖龙井的生产包含良种选育、栽培、采摘和炒制。炒制中运用抖、带、挤、甩、挺、拓、扣、抓、压、磨等手法，制茶经验在一代代茶农的实践中积累。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "West Lake Longjing production encompasses cultivar selection, cultivation, picking and pan-processing. Hand movements include shaking, drawing, squeezing, tossing, straightening, spreading, tucking, grasping, pressing and rubbing. Generations of tea farmers have developed these skills through practice.",
          "titleEn": "Tea-making craft"
        },
        {
          "key": "cultural_value",
          "titleZh": "文化与地域",
          "contentZh": "龙井茶得名于西湖茶区的龙井村。当地的种茶、采茶与制茶活动，连接着茶园生产与日常饮茶生活。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Longjing tea takes its name from Longjing village in the West Lake tea-growing area. Growing, picking and making tea connect work in the gardens with everyday tea drinking.",
          "titleEn": "Culture and place"
        }
      ],
