      "descriptionZh": "黄山毛峰以嫩芽叶手工加工，杀青、揉捻、毛火和足火各有对应的制茶动作。",
      "descriptionEn": "Huangshan Maofeng is made from tender buds and leaves. Its hand-processing links distinct actions to fixation, rolling and two firing stages.",
      "imageUrl": "",
      "videoUrl": "",
      "sourceUrl": "https://www.ihchina.cn/project_details/14608.html",
      "sourceStatus": "needs-review",
