          "titleZh": "历史脉络",
          "contentZh": "明代《农政全书》已有六安片茶的记载，清代六安瓜片被列为贡品。当时的生产制作集中在六安麻埠街一带。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "The Ming agricultural work Nongzheng Quanshu records leaf tea from Lu'an. Lu'an Guapian became a tribute tea in the Qing dynasty, when production was concentrated around Mabu in Lu'an.",
