      "descriptionZh": "碧螺春的卷曲形态与茸毫，来自揉捻整形、搓团显毫等手工工艺。",
      "descriptionEn": "Biluochun obtains its curled form and visible fine hairs through hand-rolling, shaping and rubbing the leaves into clusters.",
