          "titleZh": "文化与地域",
          "contentZh": "中山陵景区与雨花台景区是技艺流布的核心区域。特制竹篾烘笼与手工筛分、提香足干等方法相配合，形成当地针形绿茶的制作特点。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "The Sun Yat-sen Mausoleum and Yuhuatai scenic areas are core locations for this craft. Special bamboo drying baskets, hand-screening and final aroma-developing drying contribute to the local needle-shaped green tea.",
