      "keyFeatures": [
        {
          "textZh": "恩施玉露以蒸汽杀青，经抖、揉、铲、整等处理，形成细直的针形绿茶。",
          "sourceIds": [
            "ihchina-project"
          ],
          "textEn": "Enshi Yulu is a needle-shaped green tea made through steam fixation followed by shaking, rolling and shaping."
        }
      ],
      "practiceExperience": {
        "titleZh": "认识玉露的六项核心技法",
        "titleEn": "Six core techniques of Enshi Yulu",
        "kind": "techniques",
        "noteZh": "点开六项核心技法，认识蒸青与针形整形。",
        "steps": [
          {
            "id": "es-01",
            "titleZh": "蒸",
            "titleEn": "Steam",
            "contentZh": "高温蒸汽抑制酶的活性，制止茶多酚酶促氧化，并除去青草气。",
            "sourceIds": [
              "ihchina-project"
            ],
            "assetId": "A09",
            "contentEn": "Hot steam inactivates enzymes, stopping enzymatic oxidation of tea polyphenols and removing the grassy smell."
          },
          {
            "id": "es-02",
            "titleZh": "搧",
            "titleEn": "Fan and cool",
            "contentZh": "薄摊蒸青叶，搧风降温并散去水分，防止茶叶闷黄。",
            "sourceIds": [
              "ihchina-project"
            ],
            "assetId": "A10",
            "contentEn": "Steamed leaves are spread thinly and fanned to cool them and release moisture, preventing unwanted yellowing."
          },
          {
            "id": "es-03",
            "titleZh": "抖",
            "titleEn": "Shake",
            "contentZh": "在焙炉盘上捧叶抛抖、散开叶片，帮助水分蒸发。",
            "sourceIds": [
              "ihchina-project"
            ],
            "assetId": "A11",
            "contentEn": "Leaves are lifted, tossed and spread over a heated drying surface to help moisture evaporate."
          },
          {
            "id": "es-04",
            "titleZh": "揉",
            "titleEn": "Roll",
            "contentZh": "在焙炉上回转揉和对揉，使叶片卷成条形。",
            "sourceIds": [
              "ihchina-project"
            ],
            "assetId": "A12",
            "contentEn": "Circular and opposing rolling movements on the heated surface curl the leaves into strips."
          },
          {
            "id": "es-05",
            "titleZh": "铲",
            "titleEn": "Scoop and shape",
            "contentZh": "用“铲”的手法炒茶，继续蒸发水分、整理形状。",
            "sourceIds": [
              "ihchina-project"
            ],
            "assetId": "A13",
            "contentEn": "Scooping movements continue to remove moisture and shape the leaves as they are heated."
          },
          {
            "id": "es-06",
            "titleZh": "整",
            "titleEn": "Finish the shape",
            "contentZh": "通过悬手搓和依托搓整形上光，形成细直的针形。随后还需焙火提香、拣选成品。",
            "sourceIds": [
              "ihchina-project"
            ],
            "assetId": "A14",
            "contentEn": "Rubbing both above and against a supporting surface shapes and polishes the leaves into fine, straight needles. Final aroma-developing firing and sorting still follow."
          }
        ],
        "noteEn": "Explore six core techniques, from steam fixation to needle-like shaping."
      },
      "shortSummaryZh": "恩施玉露以蒸汽杀青，经抖、揉、铲、整等处理，形成细直的针形绿茶。",
