      "protectionUnit": "湖北省赵李桥茶厂",
      "descriptionZh": "赵李桥砖茶包括青砖茶与米砖茶，两者原料和加工方式各有特点。",
      "descriptionEn": "Zhaoliqiao brick tea includes green brick tea and rice brick tea, with different raw materials and processing methods.",
      "imageUrl": "",
      "videoUrl": "",
      "sourceUrl": "https://www.ihchina.cn/project_details/14627.html",
      "sourceStatus": "needs-review",
