      "detailSections": [
        {
          "key": "overview",
          "titleZh": "项目简介",
          "contentZh": "赵李桥砖茶包括青砖茶与米砖茶，两者原料和加工方式各有特点。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Zhaoliqiao brick tea includes green brick tea and rice brick tea, with different raw materials and processing methods.",
          "titleEn": "Introduction"
        },
        {
          "key": "practice",
          "titleZh": "核心工艺",
          "contentZh": "青砖茶由叶片原料经过初制、渥堆发酵、陈化、压制与烘制等处理。米砖茶以红茶茶末为原料，筛分风选后蒸制、紧压成形，再烘干包装。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Qingzhuan, or green brick tea, uses leaf material that undergoes primary processing, pile fermentation, ageing, pressing and drying. Mizhuan, or rice brick tea, uses black-tea fragments, which are screened and winnowed, steamed, compressed, dried and packed.",
          "titleEn": "Tea-making craft"
        },
        {
          "key": "history",
          "titleZh": "历史脉络",
          "contentZh": "赵李桥砖茶的前身是赤壁羊楼洞砖茶，俗称洞茶。清代当地茶厂由帽合茶逐渐改制成长方形砖茶。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Zhaoliqiao brick tea developed from Yangloudong brick tea in Chibi, commonly called Dong tea. During the Qing dynasty, local factories gradually shifted from Maohe tea to rectangular tea bricks.",
          "titleEn": "History"
        },
        {
          "key": "inheritance",
          "titleZh": "传承保护",
          "contentZh": "技艺通过师带徒延续，传习所也是相关技艺的传承场所。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Teachers pass the techniques to apprentices. Dedicated teaching centres also support their transmission.",
          "titleEn": "Passing on the tradition"
        }
      ],
