      "descriptionZh": "长盛川青砖茶将初制、渥堆发酵、精制、拼配、成型与烘干包装分为六大阶段。",
      "descriptionEn": "Changshengchuan green brick tea passes through six broad stages, from initial processing and pile fermentation to pressing, drying and packing.",
