      "detailSections": [
        {
          "key": "overview",
          "titleZh": "项目简介",
          "contentZh": "长盛川青砖茶将初制、渥堆发酵、精制、拼配、成型与烘干包装分为六大阶段。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Changshengchuan green brick tea passes through six broad stages, from initial processing and pile fermentation to pressing, drying and packing.",
          "titleEn": "Introduction"
        },
        {
          "key": "practice",
          "titleZh": "核心工艺",
          "contentZh": "初制含采摘与炒青，渥堆阶段处理茶堆水分与通风，精制进行过筛分级，拼配结合开汤评级，成型采用蒸茶紧压，最后烘干包装。大堆发酵与堆内开沟通风是其工艺特点。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Primary processing includes picking and pan-heating. Pile fermentation involves managing moisture and ventilation. Refining screens and grades the tea; blending includes infusion-based assessment. Steaming and compression shape the tea before drying and packing. Large fermentation piles with internal ventilation channels are characteristic techniques.",
          "titleEn": "Tea-making craft"
        },
        {
          "key": "cultural_value",
          "titleZh": "文化与地域",
          "contentZh": "技艺发源于湖北咸宁，流传至宜昌及周边地区。青砖茶生产与万里茶道的贸易往来相联系。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "The craft originated in Xianning, Hubei, and spread to Yichang and surrounding areas. Green brick tea production is linked to trade along the Great Tea Road.",
          "titleEn": "Culture and place"
        }
      ],
