      "id": "tea-item-30",
      "name": "黄茶制作技艺（君山银针茶制作技艺）",
      "nameEn": "Yellow Tea Processing Technique (Junshan Yinzhen)",
      "province": "湖南省",
      "city": "岳阳市君山区",
      "declaredRegion": "",
      "code": "Ⅷ-267",
      "category": "传统技艺",
      "yearBatch": "2021 第五批",
      "protectionUnit": "君山区文化馆",
      "descriptionZh": "君山银针是湖南岳阳的黄茶，制作中的两次闷黄形成了独特工艺。",
      "descriptionEn": "Junshan Yinzhen is a yellow tea from Yueyang, Hunan, with two yellowing stages in its traditional processing.",
      "imageUrl": "",
      "videoUrl": "",
      "sourceUrl": "https://www.ihchina.cn/project_details/23581.html",
      "sourceStatus": "official-partial",
      "dataQuality": "basic",
      "lastVerified": "2026-10-08",
      "detailSections": [
        {
          "key": "overview",
          "titleZh": "项目简介",
          "contentZh": "君山银针是湖南岳阳的黄茶，制作中的两次闷黄形成了独特工艺。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Junshan Yinzhen is a yellow tea from Yueyang, Hunan, with two yellowing stages in its traditional processing.",
          "titleEn": "Introduction"
        },
        {
          "key": "practice",
          "titleZh": "核心工艺",
          "contentZh": "制作包含摊晾、杀青、摊凉、初烘、初包、复烘、复包、足火与精选。初包、复包所构成的双式闷黄，是其工艺特点；成茶芽身金黄、白毫显露，外形似针。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Processing includes spreading, fixation, cooling, initial baking, first wrapping, rebaking, second wrapping, final firing and selection. The two wrapping stages produce the characteristic double yellowing process. The finished buds are golden, needle-like and covered with fine pale hairs.",
          "titleEn": "Tea-making craft"
        },
        {
          "key": "cultural_value",
          "titleZh": "文化与地域",
          "contentZh": "技艺主要分布于岳阳君山岛及许市镇等地，种茶、制茶和品饮经验与当地生活相联系。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "The craft is practised mainly on Junshan Island, in Xushi and in other parts of Yueyang. Growing, making and tasting tea are linked to local life.",
          "titleEn": "Culture and place"
        },
        {
          "key": "inheritance",
          "titleZh": "传承保护",
          "contentZh": "技艺依靠家族与师徒传承，茶园生产实践、培训及茶事体验也是传习方式。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Families and apprenticeships transmit the craft. Work in tea gardens, training and tea-related activities also provide opportunities to learn.",
          "titleEn": "Passing on the tradition"
        }
      ],
