      "descriptionEn": "Gannan Hakka lei cha is made by grinding tea and other ingredients into a paste with a bowl and pestle, then adding hot water.",
      "imageUrl": "",
      "videoUrl": "",
      "sourceUrl": "https://www.ihchina.cn/project_details/14613.html",
