      "protectionUnit": "广东省食品行业协会",
      "descriptionZh": "广东凉茶与岭南凉茶铺的生活记忆相连，配制技艺、术语和家族传承共同构成这一文化传统。",
      "descriptionEn": "Guangdong herbal-tea culture is connected with Lingnan tea shops, preparation skills, specialised terms and family transmission.",
      "imageUrl": "",
      "videoUrl": "",
      "sourceUrl": "https://www.ihchina.cn/project_details/14440.html",
      "sourceStatus": "official-partial",
