      "detailSections": [
        {
          "key": "overview",
          "titleZh": "项目简介",
          "contentZh": "广东凉茶与岭南凉茶铺的生活记忆相连，配制技艺、术语和家族传承共同构成这一文化传统。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Guangdong herbal-tea culture is connected with Lingnan tea shops, preparation skills, specialised terms and family transmission.",
          "titleEn": "Introduction"
        },
        {
          "key": "cultural_value",
          "titleZh": "文化与地域",
          "contentZh": "凉茶铺长期分布于广东、香港和澳门，成为岭南饮食生活的一部分。制茶器具、店铺、照片与史料也承载着这段文化记忆。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Herbal-tea shops have long been part of food and drink culture in Guangdong, Hong Kong and Macao. Utensils, shops, photographs and historical documents preserve memories of this tradition.",
          "titleEn": "Culture and place"
        },
        {
          "key": "inheritance",
          "titleZh": "传承保护",
          "contentZh": "凉茶配制技艺主要通过家族传承，配方与相关术语随之延续。不同凉茶品牌与配方构成了多样的地方传统。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Preparation skills are transmitted mainly through families, together with recipes and specialist vocabulary. Different brands and recipes form a diverse local tradition.",
          "titleEn": "Passing on the tradition"
        }
      ],
