          "key": "history",
          "titleZh": "历史脉络",
          "contentZh": "清末张昌翼开办张一元茶庄，以制作、销售茉莉花茶为业。1992年，张一元传统茉莉花茶制作工艺得到恢复。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Zhang Changyi opened the Zhang Yiyuan tea shop in the late Qing dynasty to make and sell jasmine tea. Its traditional jasmine-tea processing methods were revived in 1992.",
