          "titleZh": "核心工艺",
          "contentZh": "南路边茶的制作包含发酵、自然干燥、压制和包装等加工。茶汤可以与酥油、盐等调制成酥油茶。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Nanlu border tea processing includes fermentation, natural drying, pressing and packing. Its infusion can be mixed with butter, salt and other ingredients to make butter tea.",
