          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Also known by names such as Wucha, Bianxiao tea and Ya tea, it has traditionally been supplied from Ya'an to Tibet, Qinghai, and Garze and Aba in Sichuan.",
