          "titleZh": "核心工艺",
          "contentZh": "当地茶叶经杀青、揉捻后，进入初蒸、沤堆和复蒸，再经烘焙、晾置与陈化。蒸与堆的湿热处理促进叶色、香气与滋味变化。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "After fixation and rolling, the leaves undergo initial steaming, piling and steaming again, followed by baking, airing and ageing. The heat and moisture of steaming and piling bring changes in colour, aroma and taste.",
