      "id": "tea-item-43",
      "name": "黑茶制作技艺（咸阳茯茶制作技艺）",
      "nameEn": "Dark Tea Processing Technique (Xianyang Fu Tea)",
      "province": "陕西省",
      "city": "咸阳市",
      "declaredRegion": "陕西省咸阳市",
      "code": "Ⅷ-152",
      "category": "传统技艺",
