      "protectionUnit": "咸阳市群众艺术馆",
      "descriptionZh": "咸阳茯茶以黑毛茶为原料，经过筑茶成型与自然发花等工序，形成砖茶。",
      "descriptionEn": "Xianyang Fu tea uses primary-processed dark tea and includes pressing into brick form and natural flowering among its processing stages.",
      "imageUrl": "",
      "videoUrl": "",
      "sourceUrl": "https://www.ihchina.cn/project_details/23786.html",
      "sourceStatus": "official-partial",
      "dataQuality": "complete",
      "lastVerified": "2026-10-08",
      "detailSections": [
        {
          "key": "overview",
          "titleZh": "项目简介",
          "contentZh": "咸阳茯茶以黑毛茶为原料，经过筑茶成型与自然发花等工序，形成砖茶。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Xianyang Fu tea uses primary-processed dark tea and includes pressing into brick form and natural flowering among its processing stages.",
          "titleEn": "Introduction"
        },
        {
          "key": "practice",
          "titleZh": "核心工艺",
          "contentZh": "制作包括配料渥堆、煮熬茶釉、茶釉炒茶、制封灌封、扶梆筑茶、扎封锥封与自然发花。筑茶时将茶装入模具夯实成形，再捆扎茶封，进入后续发花。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "Processing includes blending and piling, boiling a concentrated tea liquor, heating the leaves with this liquor, preparing and filling wrappers, compacting in a mould, tying and piercing the wrapping, and natural flowering. Tea is packed firmly into a mould, wrapped and bound before the flowering stage.",
          "titleEn": "Tea-making craft"
        },
        {
          "key": "cultural_value",
          "titleZh": "文化与地域",
          "contentZh": "技艺主要流布于陕西咸阳泾阳、秦都一带，筑茶梆子等工具与当地茯茶加工相联系。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "The craft is practised mainly in Jingyang and Qindu in Xianyang, Shaanxi. Tea-pressing moulds and related tools are associated with local Fu tea production.",
          "titleEn": "Culture and place"
        },
        {
          "key": "inheritance",
          "titleZh": "传承保护",
          "contentZh": "技艺通过师带徒、家族传承与院校培训延续，传承馆也承担展示与传播作用。",
          "sourceIds": [
            "ihchina-project"
          ],
          "contentEn": "The craft continues through apprenticeships, family transmission and institutional training. Heritage exhibition centres also present and share it.",
          "titleEn": "Passing on the tradition"
        }
      ],
